  var sourceState=CombatAccess.field(CombatAccess.field(caster,"timedStatus"),"sourcePoisonLifecycle");var sourceLife=CombatAccess.field(sourceState,"sourceNpcOwner");set(sourceState,"sourceNpcOwner",new Object());check(!intent.before()&&queued.before(),"caster life ABA cannot authorize new recovery or revoke target event");set(sourceState,"sourceNpcOwner",sourceLife);
  set(pc,"selectedCharacter","replacement-target");check(!intent.before()&&!queued.before(),"same object replacement target role cannot receive old signed HP");set(pc,"selectedCharacter","target");set(pc,"selectedClassicServerName","other-source");check(!intent.before()&&!queued.before(),"cross-source target cannot inherit heal");set(pc,"selectedClassicServerName","detached-source");set(pc,"account","other-account");check(!intent.before()&&!queued.before(),"different account target cannot inherit heal");set(pc,"account","detached-account");
  var state=CombatAccess.field(CombatAccess.field(pc,"timedStatus"),"sourcePoisonLifecycle");var targetLife=CombatAccess.field(state,"sourceNpcOwner");set(state,"sourceNpcOwner",new Object());check(!intent.before()&&!queued.before(),"same role resurrection cannot inherit queued old heal");set(state,"sourceNpcOwner",targetLife);set(pc,"sourceItemDisconnected",true);check(!intent.before()&&!queued.before(),"disconnected target cannot receive heal");set(pc,"sourceItemDisconnected",false);set(pc,"playerHp",0);check(!intent.before(),"dead target cannot admit recovery or be resurrected");set(pc,"playerHp",40);
  set(pc,"positionX",20);set(pc,"positionY",20);check(intent.before()&&queued.before(),"original admitted healing does not require old position");set(caster,"currentRoomId",2L);check(!intent.before()&&queued.before(),"wrong original room rejected before enqueue, later source retirement leaves admitted target independent");set(caster,"currentRoomId",1L);set(hub,"nativeStaticMotionClosed",true);check(!intent.before()&&!NativeSourceRawDamage.beforeEvent(pc,event),"Main close rejects new submission and actual raw FIFO boundary");set(hub,"nativeStaticMotionClosed",false);set(life,"mode",NativePlayerLifetime.Mode.DRAINING);check(!intent.before()&&NativeSourceRawDamage.beforeEvent(pc,event),"draining prevents new recovery but preserves already admitted raw target event");set(life,"mode",NativePlayerLifetime.Mode.STOPPED);check(!intent.before()&&!NativeSourceRawDamage.beforeEvent(pc,event),"stopped retires both producer and queued target HP");set(life,"mode",NativePlayerLifetime.Mode.OPEN);
  check(NativeSourceSignedRecovery.capture(pc,null)==null,"original missing caster remains handled drop");var context=(NativeAreaMaterialAction.Context)unsafe().allocateInstance(NativeAreaMaterialAction.Context.class);set(context,"bindings",new IdentityHashMap<ClientSession,NativePlayerCommit.Binding>());var previous=NativeAreaMaterialAction.current.get();try{NativeAreaMaterialAction.current.set(context);check(NativeSourceSignedRecovery.capture(pc,caster)==null,"existing prewait context cannot adopt missing or new target binding");}finally{if(previous==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(previous);}
  var originalActor=new NativeSourceDamageDisplay.Actor(caster,source.binding,source.life,0,0);set(context,"nativeSourceMagicSnapshot",new NativeSourceMagicNpc.Snapshot(originalActor,Map.of(),List.of(),Map.of(),Map.of()));set(sourceState,"sourceNpcOwner",new Object());var inherited=NativeSourceSignedRecovery.member(caster,source.binding,context);check(inherited.life==source.life&&!inherited.current(false),"existing magic snapshot preserves old life rather than adopting replacement after earlier wait");set(sourceState,"sourceNpcOwner",sourceLife);
  var raw=(NativeSourceRawDamage.Action)unsafe().allocateInstance(NativeSourceRawDamage.Action.class);var members=new IdentityHashMap<ClientSession,NativeSourceRawDamage.Member>();members.put(caster,source);set(raw,"members",members);set(context,"nativeSourceRawAction",raw);check(NativeSourceSignedRecovery.member(caster,source.binding,context)==source,"existing raw ingress retains exact original Member and accepted token");var otherBinding=new NativePlayerCommit.Binding(source.binding.owner(),source.binding.object(),source.binding.source(),source.binding.account(),"other",source.binding.phase(),source.binding.room(),source.binding.map(),source.binding.instance());check(NativeSourceSignedRecovery.member(caster,otherBinding,context)==null,"existing raw member cannot be rebound to a different selected role");set(context,"nativeSourceRawAction",null);check(NativeSourceSignedRecovery.member(caster,otherBinding,context)==null,"existing magic snapshot cannot authorize different binding");
  var action=(NativeSourceDollAction.Action)unsafe().allocateInstance(NativeSourceDollAction.Action.class);var physicalLife=new Object();var physicalActor=new NativeSourceDamageDisplay.Actor(caster,source.binding,physicalLife,0,0);set(action,"stamp",new NativeSourceDollAction.Stamp(caster,physicalActor,null,null,new java.util.concurrent.atomic.AtomicReference<RuntimeInventory.Item>()));set(context,"nativeSourceDollAction",action);check(NativeSourceSignedRecovery.member(caster,source.binding,context).life==physicalLife,"earlier physical ingress life takes precedence over later generic magic snapshot");
